    for strategy,label in [('initial','初始'),('active','主动补算'),('random','随机补算')]: # Keep the matched experimental arms in their registered order.
        for split,title in [('test','普通测试'),('ood','域外测试')]: # Preserve separate denominators instead of combining their means implicitly.
            item=branch['learning']['results'][strategy][split];cells=[label,title,str(item['count']),f"{item['mean_channel_relative_L2']*100:.3f}%",str(item['negative_examples']),str(item['accuracy_pass'])];rows.append('<tr>'+''.join('<td>'+html.escape(value)+'</td>' for value in cells)+'</tr>') # Read measured error-negative and accuracy counts directly from the frozen test summary.
