def physical_path(raw): # Relocate downloaded evidence while preserving its original repository-relative suffix.
    path=Path(raw) # Prefer the exact existing current workspace path.
    if path.exists(): return path # Use existing evidence without guessing another location.
    text=str(raw);marker='/build/' # Identify the portable repository result boundary.
    return REPO/'build'/text.split(marker,1)[1] if marker in text else REPO/path # Support the documented extraction layout.
